mapper.update:
update pay_order
set refund_amount = refund_amount + #{refundAmount}
where id = #{orderId}

mapper.select:
select id as orderId, order_no as orderNo, mch_id as mchId, mch_no as mchNo, isv_id as isvId, isv_no as isvNo, mch_name as mchName, mch_type as mchType, mch_order_no as mchOrderNo, if_code as channelCode, total_amount as totalAmount, pay_amount as payAmount, promotion_amount as promotionAmount, mch_fee_rate as mchFeeRate, currency, state, channel_extra as channelExtra, channel_user as channelUser, channel_order_no as channelOrderNo, refund_state as refundState, refund_amount as refundAmount, has_division as hasDivision, division_mode as divisionMode, division_state as divisionState, expired_time as expiredTime, success_time as successTime, create_time as createTime, update_time as updateTime, notify_state as notifyState from pay_order
and id = #{payOrderPage.orderId}
and order_no = #{payOrderPage.orderNo}
and mch_id = #{payOrderPage.mchId}
and mch_no = #{payOrderPage.mchNo}
and if_code = #{payOrderPage.channelCode}
and mch_name LIKE CONCAT('%', #{payOrderPage.mchName}, '%')
and notify_state = #{payOrderPage.notifyState}
order by create_time desc
